INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Adresse an ein einziges Gerät gesendet wird?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast geht an mehrere"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Adresstyp sendet Daten an eine Gruppe von Geräten?', 3, '[{"text": "Multicast", "correct": true, "because": "An mehrere Empfänger"}, {"text": "Unicast", "correct": false, "because": "Nur ein Gerät"}, {"text": "Anycast", "correct": false, "because": "Nächstgelegenes Gerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen gibt es für die Adressierung in IPv6?', 5, '[{"text": "Unicast", "correct": true, "because": "Einzelgerät"}, {"text": "Multicast", "correct": true, "because": "Gruppen"}, {"text": "Anycast", "correct": true, "because": "Nächstgelegenes Ziel"}, {"text": "Broadcast", "correct": false, "because": "Nicht in IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unicast adressiert ein Gerät. b) Multicast ist wie Broadcast in IPv4.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Multicast ersetzt Broadcast"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Adresse in einem Netzwerk nutze?', 4, '[{"text": "Adresstyp", "correct": false, "because": "Bestimmt Kommunikation"}, {"text": "Scope", "correct": false, "because": "Definiert Reichweite"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ::1 nur für Server ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Loopback für jedes Gerät"}, {"text": "Ja", "correct": false, "because": "Allgemeine Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist für lokale Tests reserviert?', 3, '[{"text": "::1", "correct": true, "because": "IPv6-Loopback"}, {"text": "ff00::/8", "correct": false, "because": "Multicast"}, {"text": "fe80::/10", "correct": false, "because": "Link-Local"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Unicast-Adresse?', 5, '[{"text": "Einzelgerät", "correct": true, "because": "Ein Empfänger"}, {"text": "Global routbar", "correct": true, "because": "Öffentlich möglich"}, {"text": "Link-Local möglich", "correct": true, "because": "Lokale Nutzung"}, {"text": "An alle Geräte", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) fe80::/10 für Link-Local ist und b) ff00::/8 für Unicast. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ff00::/8 ist Multicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Adresstyp zu bestimmen?', 4, '[{"text": "Präfix", "correct": false, "because": "Definiert Typ"}, {"text": "Scope", "correct": false, "because": "Bestimmt Reichweite"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ff00::/8 für Einzelgeräte?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast-Bereich"}, {"text": "Ja", "correct": false, "because": "Falscher Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen nutzen spezielle Präfixe?', 4, '[{"text": "Link-Local", "correct": true, "because": "fe80::/10"}, {"text": "Multicast", "correct": true, "because": "ff00::/8"}, {"text": "Global Unicast", "correct": false, "because": "Kein festes Präfix"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anycast an alle Geräte sendet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur nächstgelegenes Gerät"}, {"text": "Ja", "correct": false, "because": "Multicast tut das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Multicast-Adresse?', 3, '[{"text": "Gruppenkommunikation", "correct": true, "because": "An mehrere senden"}, {"text": "Einzelgerät testen", "correct": false, "because": "Unicast/Loopback"}, {"text": "Design verbessern", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ::1 ist Loopback. b) fe80::/10 ist global routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "fe80::/10 nur lokal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Link-Local-Adresse?', 4, '[{"text": "Lokale Kommunikation", "correct": true, "because": "Nur im Segment"}, {"text": "Globale Weiterleitung", "correct": false, "because": "Nicht routbar"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Broadcast in IPv6 existiert?', 2, '[{"text": "Nein", "correct": true, "because": "Multicast ersetzt es"}, {"text": "Ja", "correct": false, "because": "Nicht vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten spezielle Adresstypen?', 5, '[{"text": "Effiziente Kommunikation", "correct": true, "because": "Multicast spart Bandbreite"}, {"text": "Lokale Tests", "correct": true, "because": "Loopback hilft"}, {"text": "Flexibles Routing", "correct": true, "because": "Anycast optimiert"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Anycast für lokale Netze?', 3, '[{"text": "Nein", "correct": true, "because": "Nächstgelegenes Ziel, oft global"}, {"text": "Ja", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Multicast?', 4, '[{"text": "Video an mehrere Geräte streamen", "correct": true, "because": "Gruppenkommunikation"}, {"text": "Lokalen Testlauf", "correct": false, "because": "Loopback"}, {"text": "Einzelgerät adressieren", "correct": false, "because": "Unicast"}]');
